INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter einem Betriebssystem?', 2, '[{"text": "Software zur Hardwareverwaltung", "correct": true, "because": "Steuert Ressourcen"}, {"text": "Anwendungsprogramm", "correct": false, "because": "Andere Kategorie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Betriebssystem?', 3, '[{"text": "Effiziente Nutzung von Ressourcen", "correct": true, "because": "Hardware und Software koordinieren"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Design verbessern", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben hat ein Betriebssystem?', 5, '[{"text": "Prozessmanagement", "correct": true, "because": "Verwaltet Aufgaben"}, {"text": "Speicherverwaltung", "correct": true, "because": "RAM organisieren"}, {"text": "Marketing", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Betriebssystem verwaltet Hardware. b) Es ist nur für Server nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für Clients"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines Betriebssystems?', 4, '[{"text": "Kompatibilität", "correct": false, "because": "Wichtig für Software"}, {"text": "Systemanforderungen", "correct": false, "because": "Hardware entscheidend"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Betriebssystem Multitasking unterstützt?', 2, '[{"text": "Ja", "correct": true, "because": "Mehrere Prozesse gleichzeitig"}, {"text": "Nein", "correct": false, "because": "Standardfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Betriebssystem ist für Server häufig im Einsatz?', 3, '[{"text": "Linux", "correct": true, "because": "Stabil und flexibel"}, {"text": "Photoshop", "correct": false, "because": "Keine OS"}, {"text": "Excel", "correct": false, "because": "Keine OS"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Verwaltung durch ein Betriebssystem?', 5, '[{"text": "Dateisystem", "correct": true, "because": "Speicherorganisation"}, {"text": "Treiber", "correct": true, "because": "Hardwarekommunikation"}, {"text": "Bürogestaltung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Betriebssystem koordiniert Prozesse. b) Es ist nur für PCs nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Server, Mobilgeräte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Betriebssystem unwichtig?', 4, '[{"text": "Stabilität", "correct": false, "because": "Kernanforderung"}, {"text": "Sicherheit", "correct": false, "because": "Schutz wichtig"}, {"text": "Farbe der Oberfläche", "correct": true, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Betriebssystem Treiber enthalten?', 2, '[{"text": "Nein", "correct": true, "because": "Können nachträglich installiert werden"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Betriebssystem für Fachinformatiker?', 4, '[{"text": "Ressourcenmanagement", "correct": true, "because": "Effiziente Nutzung"}, {"text": "Nutzerfreundlichkeit", "correct": true, "because": "Einfache Bedienung"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Betriebssystem immer grafisch ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Kommandozeilen-OS"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Betriebssystem?', 3, '[{"text": "Stabilität", "correct": true, "because": "Sichert Betrieb"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Betriebssystem verwaltet Speicher. b) Es ist nur für Desktop-PCs nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Server, Mobilgeräte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein schlechtes Betriebssystem?', 5, '[{"text": "Instabilität", "correct": true, "because": "Abstürze möglich"}, {"text": "Sicherheitslücken", "correct": true, "because": "Angriffe erleichtert"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker beim Betriebssystem?', 3, '[{"text": "Installation und Konfiguration", "correct": true, "because": "Sichert Funktion"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Betriebssystem virtualisiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. mit VMware"}, {"text": "Nein", "correct": false, "because": "Häufig genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Betriebssystem ist Open Source?', 4, '[{"text": "Linux", "correct": true, "because": "Freier Quellcode"}, {"text": "Windows", "correct": false, "because": "Proprietär"}, {"text": "macOS", "correct": false, "because": "Proprietär"}]');
